public static String extractAcronym(String input) {
    String result = "";
    boolean looking = true;
    for (int i = 0; i < input.length(); i++) {
        if (looking && input.charAt(i) != ’#’) {
            result += input.charAt(i);
            looking = false;
        }
        if (input.charAt(i) == ’#’) {
            looking = true;
        }
    }
    return result;
}


 Alternate solution:

public static String extractAcronym(String input) {
    return input.replaceAll("((?<=[^#])[^#]*#*)|^#*", "");
}

